const std = @import("std"); const builtin = @import("builtin"); const stor = @import("tk-task-stor.zig");
const tszz = std.testing; const Task = stor.Task; const Reje = stor.Reje; const vali = stor.vali; const norm = stor.norm; const chaiFind = stor.chaiFind; const idenVali = stor.idenVali; const autoRunz = stor.autoRunz;
fn testJson(allo: std.mem.Allocator, text: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, text, .{}) catch unreachable; }
test "a chai is dropped for a nested chai, a claimed member, or a bad / scriptless virtual id" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const task_list = [_]Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "b", .type = "hand", .run = "x" }, .{ .id = "c1", .type = "chai", .ids = &.{ "a", "b" } }, .{ .id = "c2", .type = "chai", .ids = &.{"a"} }, .{ .id = "c3", .type = "chai", .ids = &.{ "zzz", "a-virtual" } }, .{ .id = "c4", .type = "chai", .ids = &.{"c1"} }, .{ .id = "c5", .type = "chai", .ids = &.{"has space"} }, .{ .id = "c6", .type = "chai", .ids = &.{"zzz"} } }; for ([_]bool{ true, false }) |scri_okay| { var keep: std.ArrayList(Task) = .empty; var kidz: std.ArrayList(usize) = .empty; var badz: std.ArrayList(Reje) = .empty; for (task_list, 0..) |task, indx| { try keep.append(allo, task); try kidz.append(allo, indx); } stor.chaiBadzDrop(allo, &keep, &kidz, &badz, scri_okay); if (scri_okay) { try tszz.expectEqual(@as(usize, 4), keep.items.len); try tszz.expectEqualStrings("c2", badz.items[0].iden); try tszz.expectEqual(@as(usize, 3), badz.items[0].inde); try tszz.expectEqual(@as(usize, 4), badz.items.len); try tszz.expect(chaiFind(keep.items, "a") != null); try tszz.expect(chaiFind(keep.items, "zzz") != null); try tszz.expect(chaiFind(keep.items, "c1") == null); } else { try tszz.expectEqual(@as(usize, 3), keep.items.len); } } }
